CREATE VIEW content_transition_selected_roots_level0_0 AS SELECT t.id transition_id,'asset_file_references' root_table,json_array(a."logical_key") root_key FROM content_transitions t JOIN "asset_file_references" a WHERE ((EXISTS(SELECT 1 FROM members m WHERE m.uid IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members')) AND (a.logical_key LIKE 'members/'||m.code||'/backgrounds/%' OR a.logical_key='profile/'||m.code||'.webp' OR a.logical_key='profile/signatures/'||m.code||'.png' OR EXISTS(SELECT 1 FROM member_profile_images image WHERE image.member_uid=m.uid AND image.image_url='/r2-assets/'||a.logical_key))) OR EXISTS(SELECT 1 FROM notices n WHERE (n.thumbnail_url='/r2-assets/'||a.logical_key OR EXISTS(SELECT 1 FROM json_each(n.image_urls) image WHERE image.value='/r2-assets/'||a.logical_key)) AND (n.publisher_member_uid IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members')) OR EXISTS(SELECT 1 FROM json_each(n.related_member_uids) member WHERE member.value IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members'))))) OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='asset_file_references' AND json_extract(decision.value,'$.key')=json_array(a."logical_key") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='asset_file_references' AND json_extract(decision.value,'$.key')=json_array(a."logical_key") AND json_extract(decision.value,'$.disposition')='exclude'))
UNION ALL
SELECT t.id transition_id,'chzzk_api_cache' root_table,json_array(a."key") root_key FROM content_transitions t JOIN "chzzk_api_cache" a WHERE ((0 OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='chzzk_api_cache' AND json_extract(decision.value,'$.key')=json_array(a."key") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='chzzk_api_cache' AND json_extract(decision.value,'$.key')=json_array(a."key") AND json_extract(decision.value,'$.disposition')='exclude'))
UNION ALL
SELECT t.id transition_id,'ddays' root_table,json_array(a."id") root_key FROM content_transitions t JOIN "ddays" a WHERE ((0 OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='ddays' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='ddays' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='exclude'))
UNION ALL
SELECT t.id transition_id,'kirinuki_channels' root_table,json_array(a."id") root_key FROM content_transitions t JOIN "kirinuki_channels" a WHERE ((0 OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='kirinuki_channels' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='kirinuki_channels' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='exclude'))
UNION ALL
SELECT t.id transition_id,'members' root_table,json_array(a."uid") root_key FROM content_transitions t JOIN "members" a WHERE ((a.uid IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members')) OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='members' AND json_extract(decision.value,'$.key')=json_array(a."uid") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='members' AND json_extract(decision.value,'$.key')=json_array(a."uid") AND json_extract(decision.value,'$.disposition')='exclude'));
--> statement-breakpoint
CREATE VIEW content_transition_selected_roots_level0_1 AS SELECT t.id transition_id,'music_catalog_meta' root_table,json_array(a."id") root_key FROM content_transitions t JOIN "music_catalog_meta" a WHERE ((0 OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='music_catalog_meta' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='music_catalog_meta' AND json_extract(decision.value,'$.key')=json_array(a."id") AND json_extract(decision.value,'$.disposition')='exclude'))
UNION ALL
