    ) SELECT DISTINCT c.transition_id,c.row_table root_table,c.row_key root_key FROM closure c JOIN content_transitions t ON t.id=c.transition_id WHERE CASE c.row_table WHEN 'asset_file_references' THEN EXISTS(SELECT 1 FROM "asset_file_references" a WHERE a."logical_key"=json_extract(c.row_key,'$[0]') AND ((EXISTS(SELECT 1 FROM members m WHERE m.uid IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members')) AND (a.logical_key LIKE 'members/'||m.code||'/backgrounds/%' OR a.logical_key='profile/'||m.code||'.webp' OR a.logical_key='profile/signatures/'||m.code||'.png' OR EXISTS(SELECT 1 FROM member_profile_images image WHERE image.member_uid=m.uid AND image.image_url='/r2-assets/'||a.logical_key))) OR EXISTS(SELECT 1 FROM notices n WHERE (n.thumbnail_url='/r2-assets/'||a.logical_key OR EXISTS(SELECT 1 FROM json_each(n.image_urls) image WHERE image.value='/r2-assets/'||a.logical_key)) AND (n.publisher_member_uid IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members')) OR EXISTS(SELECT 1 FROM json_each(n.related_member_uids) member WHERE member.value IN (SELECT iif(t.local_site=t.source_site,json_extract(value,'$.uid'),json_extract(value,'$.targetUid')) FROM json_each(t.plan_json,'$.members'))))) OR EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='asset_file_references' AND json_extract(decision.value,'$.key')=json_array(a."logical_key") AND json_extract(decision.value,'$.disposition')='include')) AND NOT EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.classifications') decision WHERE json_extract(decision.value,'$.table')='asset_file_references' AND json_extract(decision.value,'$.key')=json_array(a."logical_key") AND json_extract(decision.value,'$.disposition')='exclude')))
