CREATE VIEW content_transition_prepared_validation_membership AS WITH RECURSIVE closure(transition_id,root_table,root_key,row_table,row_key) AS (
    SELECT r.transition_id,r.root_table,r.root_key,r.root_table,r.root_key FROM content_transition_selected_roots r JOIN content_transitions t ON t.id=r.transition_id WHERE t.local_site=t.source_site AND t.phase='prepared'
    UNION SELECT c.transition_id,c.root_table,c.root_key,CASE e.value WHEN 0 THEN 'music_ai_reviews' WHEN 1 THEN 'music_ai_review_batches' WHEN 2 THEN 'music_ai_reviews' WHEN 3 THEN 'music_channels' WHEN 4 THEN 'music_channels' WHEN 5 THEN 'music_entities' WHEN 6 THEN 'music_channel_upload_monitors' WHEN 7 THEN 'music_ingestion_candidates' WHEN 8 THEN 'music_channels' WHEN 9 THEN 'music_cover_proposals' WHEN 10 THEN 'music_entities' WHEN 11 THEN 'members' WHEN 12 THEN 'music_cover_proposals' WHEN 13 THEN 'music_entities' WHEN 14 THEN 'members' WHEN 15 THEN 'music_songs' WHEN 16 THEN 'music_performances' WHEN 17 THEN 'members' WHEN 18 THEN 'music_entities' WHEN 19 THEN 'music_ingestion_candidates' WHEN 20 THEN 'music_ingestion_jobs' WHEN 21 THEN 'music_performances' WHEN 22 THEN 'music_ingestion_jobs' WHEN 23 THEN 'music_ingestion_candidates' WHEN 24 THEN 'music_media_sources' WHEN 25 THEN 'music_media_sources' WHEN 26 THEN 'music_channels' WHEN 27 THEN 'music_performances' WHEN 28 THEN 'music_entities' WHEN 29 THEN 'music_performances' WHEN 30 THEN 'music_media_sources' END,CASE e.value WHEN 0 THEN json_array(b0."id") WHEN 1 THEN json_array(b1."id") WHEN 2 THEN json_array(b2."id") WHEN 3 THEN json_array(b3."id") WHEN 4 THEN json_array(b4."id") WHEN 5 THEN json_array(b5."id") WHEN 6 THEN json_array(b6."id") WHEN 7 THEN json_array(b7."id") WHEN 8 THEN json_array(b8."id") WHEN 9 THEN json_array(b9."id") WHEN 10 THEN json_array(b10."id") WHEN 11 THEN json_array(b11."uid") WHEN 12 THEN json_array(b12."id") WHEN 13 THEN json_array(b13."id") WHEN 14 THEN json_array(b14."uid") WHEN 15 THEN json_array(b15."id") WHEN 16 THEN json_array(b16."id") WHEN 17 THEN json_array(b17."uid") WHEN 18 THEN json_array(b18."id") WHEN 19 THEN json_array(b19."id") WHEN 20 THEN json_array(b20."id") WHEN 21 THEN json_array(b21."id") WHEN 22 THEN json_array(b22."id") WHEN 23 THEN json_array(b23."id") WHEN 24 THEN json_array(b24."id") WHEN 25 THEN json_array(b25."id") WHEN 26 THEN json_array(b26."id") WHEN 27 THEN json_array(b27."id") WHEN 28 THEN json_array(b28."id") WHEN 29 THEN json_array(b29."id") WHEN 30 THEN json_array(b30."id") END FROM closure c CROSS JOIN json_each(CASE c.row_table WHEN 'music_ai_review_attempts' THEN '[0]' WHEN 'music_ai_review_batch_items' THEN '[1]' WHEN 'music_ai_review_requests' THEN '[2]' WHEN 'music_channel_automation_approvals' THEN '[3]' WHEN 'music_channel_entities' THEN '[4,5]' WHEN 'music_channel_upload_candidate_origins' THEN '[6,7]' WHEN 'music_channel_upload_monitors' THEN '[8]' WHEN 'music_cover_proposal_original_artists' THEN '[9,10,11]' WHEN 'music_cover_proposal_participants' THEN '[12,13,14]' WHEN 'music_cover_proposals' THEN '[15,16]' WHEN 'music_entities' THEN '[17]' WHEN 'music_entity_aliases' THEN '[18]' WHEN 'music_ingestion_candidate_origins' THEN '[19,20]' WHEN 'music_ingestion_candidates' THEN '[21]' WHEN 'music_ingestion_events' THEN '[22,23]' WHEN 'music_media_source_relations' THEN '[24,25]' WHEN 'music_media_sources' THEN '[26]' WHEN 'music_performance_participants' THEN '[27,28]' WHEN 'music_performance_sources' THEN '[29,30]' ELSE '[]' END) e LEFT JOIN "music_ai_review_attempts" a0 ON e.value=0 AND c.row_table='music_ai_review_attempts' AND a0."token"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_ai_reviews" b0 ON a0."review_id"=b0."id"
LEFT JOIN "music_ai_review_batch_items" a1 ON e.value=1 AND c.row_table='music_ai_review_batch_items' AND a1."id"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_ai_review_batches" b1 ON a1."batch_id"=b1."id"
LEFT JOIN "music_ai_review_requests" a2 ON e.value=2 AND c.row_table='music_ai_review_requests' AND a2."request_key"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_ai_reviews" b2 ON a2."review_id"=b2."id"
LEFT JOIN "music_channel_automation_approvals" a3 ON e.value=3 AND c.row_table='music_channel_automation_approvals' AND a3."channel_id"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_channels" b3 ON a3."channel_id"=b3."id"
LEFT JOIN "music_channel_entities" a4 ON e.value=4 AND c.row_table='music_channel_entities' AND a4."channel_id"=json_extract(c.row_key,'$[0]') AND a4."entity_id"=json_extract(c.row_key,'$[1]') LEFT JOIN "music_channels" b4 ON a4."channel_id"=b4."id"
LEFT JOIN "music_channel_entities" a5 ON e.value=5 AND c.row_table='music_channel_entities' AND a5."channel_id"=json_extract(c.row_key,'$[0]') AND a5."entity_id"=json_extract(c.row_key,'$[1]') LEFT JOIN "music_entities" b5 ON a5."entity_id"=b5."id"
