LEFT JOIN "music_channel_upload_candidate_origins" a7 ON e.value=7 AND c.row_table='music_channel_upload_candidate_origins' AND a7."monitor_id"=json_extract(c.row_key,'$[0]') AND a7."candidate_id"=json_extract(c.row_key,'$[1]') LEFT JOIN "music_ingestion_candidates" b7 ON a7."candidate_id"=b7."id"
