LEFT JOIN "music_cover_proposal_participants" a14 ON e.value=14 AND c.row_table='music_cover_proposal_participants' AND a14."proposal_id"=json_extract(c.row_key,'$[0]') AND a14."credit_order"=json_extract(c.row_key,'$[1]') LEFT JOIN "members" b14 ON a14."submitted_member_uid"=b14."uid"
LEFT JOIN "music_cover_proposals" a15 ON e.value=15 AND c.row_table='music_cover_proposals' AND a15."id"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_songs" b15 ON a15."suggested_song_id"=b15."id"
LEFT JOIN "music_cover_proposals" a16 ON e.value=16 AND c.row_table='music_cover_proposals' AND a16."id"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_performances" b16 ON a16."approved_performance_id"=b16."id"
LEFT JOIN "music_entities" a17 ON e.value=17 AND c.row_table='music_entities' AND a17."id"=json_extract(c.row_key,'$[0]') LEFT JOIN "members" b17 ON a17."member_uid"=b17."uid"
LEFT JOIN "music_entity_aliases" a18 ON e.value=18 AND c.row_table='music_entity_aliases' AND a18."entity_id"=json_extract(c.row_key,'$[0]') AND a18."normalized_alias"=json_extract(c.row_key,'$[1]') LEFT JOIN "music_entities" b18 ON a18."entity_id"=b18."id"
LEFT JOIN "music_ingestion_candidate_origins" a19 ON e.value=19 AND c.row_table='music_ingestion_candidate_origins' AND a19."id"=json_extract(c.row_key,'$[0]') LEFT JOIN "music_ingestion_candidates" b19 ON a19."candidate_id"=b19."id"
