UNION SELECT c.transition_id,c.root_table,c.root_key,CASE e.value WHEN 0 THEN 'music_performances' WHEN 1 THEN 'music_songs' WHEN 2 THEN 'music_playlist_work_queues' WHEN 3 THEN 'music_playlist_work_batches' WHEN 4 THEN 'music_songs' WHEN 5 THEN 'music_songs' WHEN 6 THEN 'music_entities' WHEN 7 THEN 'music_songs' WHEN 8 THEN 'music_songs' WHEN 9 THEN 'naver_cafe_sources' WHEN 10 THEN 'members' WHEN 11 THEN 'x_posts' WHEN 12 THEN 'members' WHEN 13 THEN 'youtube_feed_sources' WHEN 14 THEN 'member_links' WHEN 15 THEN 'member_profile_images' WHEN 16 THEN 'music_performance_participants' WHEN 17 THEN 'music_performance_sources' WHEN 18 THEN 'music_performance_tags' WHEN 19 THEN 'music_song_aliases' WHEN 20 THEN 'music_song_original_artists' WHEN 21 THEN 'music_song_tags' WHEN 22 THEN 'music_entity_aliases' WHEN 23 THEN 'music_channel_entities' WHEN 24 THEN 'music_cover_proposal_original_artists' WHEN 25 THEN 'music_cover_proposal_participants' WHEN 26 THEN 'music_media_source_relations' WHEN 27 THEN 'music_ingestion_candidate_origins' WHEN 28 THEN 'music_channel_upload_candidate_origins' WHEN 29 THEN 'music_ingestion_events' WHEN 30 THEN 'music_ai_reviews' END,CASE e.value WHEN 0 THEN json_array(b0."id") WHEN 1 THEN json_array(b1."id") WHEN 2 THEN json_array(b2."id") WHEN 3 THEN json_array(b3."id") WHEN 4 THEN json_array(b4."id") WHEN 5 THEN json_array(b5."id") WHEN 6 THEN json_array(b6."id") WHEN 7 THEN json_array(b7."id") WHEN 8 THEN json_array(b8."id") WHEN 9 THEN json_array(b9."id") WHEN 10 THEN json_array(b10."uid") WHEN 11 THEN json_array(b11."id") WHEN 12 THEN json_array(b12."uid") WHEN 13 THEN json_array(b13."id") WHEN 14 THEN json_array(b14."id") WHEN 15 THEN json_array(b15."id") WHEN 16 THEN json_array(b16."performance_id",b16."entity_id") WHEN 17 THEN json_array(b17."performance_id",b17."source_id",b17."start_seconds") WHEN 18 THEN json_array(b18."performance_id",b18."tag_key") WHEN 19 THEN json_array(b19."song_id",b19."normalized_alias") WHEN 20 THEN json_array(b20."song_id",b20."entity_id") WHEN 21 THEN json_array(b21."song_id",b21."tag_key") WHEN 22 THEN json_array(b22."entity_id",b22."normalized_alias") WHEN 23 THEN json_array(b23."channel_id",b23."entity_id") WHEN 24 THEN json_array(b24."proposal_id",b24."credit_order") WHEN 25 THEN json_array(b25."proposal_id",b25."credit_order") WHEN 26 THEN json_array(b26."source_id",b26."related_source_id",b26."relation_type") WHEN 27 THEN json_array(b27."id") WHEN 28 THEN json_array(b28."monitor_id",b28."candidate_id") WHEN 29 THEN json_array(b29."id") WHEN 30 THEN json_array(b30."id") END FROM closure c CROSS JOIN json_each(CASE c.row_table WHEN 'music_performance_tags' THEN '[0]' WHEN 'music_performances' THEN '[1,16,17,18]' WHEN 'music_playlist_work_batches' THEN '[2]' WHEN 'music_playlist_work_items' THEN '[3]' WHEN 'music_song_aliases' THEN '[4]' WHEN 'music_song_original_artists' THEN '[5,6]' WHEN 'music_song_tags' THEN '[7]' WHEN 'music_songs' THEN '[8,19,20,21]' WHEN 'naver_cafe_posts' THEN '[9]' WHEN 'schedule_day_assessments' THEN '[10]' WHEN 'x_post_references' THEN '[11]' WHEN 'youtube_feed_sources' THEN '[12]' WHEN 'youtube_feed_videos' THEN '[13]' WHEN 'members' THEN '[14,15]' WHEN 'music_entities' THEN '[22]' WHEN 'music_channels' THEN '[23]' WHEN 'music_cover_proposals' THEN '[24,25]' WHEN 'music_media_sources' THEN '[26]' WHEN 'music_ingestion_candidates' THEN '[27,28,29,30]' ELSE '[]' END) e LEFT JOIN "music_performance_tags" a0 ON e.value=0 AND c.row_table='music_performance_tags' AND a0."performance_id"=json_extract(c.row_key,'$[0]') AND a0."tag_key"=json_extract(c.row_key,'$[1]') LEFT JOIN "music_performances" b0 ON a0."performance_id"=b0."id"
