CREATE VIEW content_transition_validation_images AS SELECT j.transition_id,j.row_table,j.row_key,j.after_json image_json,j.commit_seq FROM content_transition_journal j JOIN content_transitions t ON t.id=j.transition_id WHERE t.local_site=t.source_site AND t.phase<>'prepared' AND j.after_json IS NOT NULL AND j.row_table IN ('chzzk_api_cache','music_ai_review_batch_items','music_ai_review_batches','music_ai_reviews','music_catalog_events','music_cover_proposals','music_ingestion_candidates','music_ingestion_events','music_performances','notices','pending_schedules','schedule_candidate_rejections','x_api_cache','x_posts','youtube_api_cache')
