d(json_extract(i.image_json,'$.'||json_extract(field.value,'$[0]')))) valid_json FROM images i CROSS JOIN json_each(CASE i.row_table WHEN 'chzzk_api_cache' THEN '[["value","chzzk_cache"]]' WHEN 'music_ai_review_batch_items' THEN '[["result_json","ai_result"]]' WHEN 'music_ai_review_batches' THEN '[["selection_json","ai_selection"]]' WHEN 'music_ai_reviews' THEN '[["range_json","range"],["input_json","ai_input"],["result_json","ai_result"]]' WHEN 'music_catalog_events' THEN '[["before_json","catalog_event"],["after_json","catalog_event"],["detail_json","catalog_event"]]' WHEN 'music_cover_proposals' THEN '[["submitted_broadcast_json","broadcast"],["submitted_tags_json","strings"],["approved_performance_snapshot_json","approved_snapshot"]]' WHEN 'music_ingestion_candidates' THEN '[["review_input_json","review_input"]]' WHEN 'music_ingestion_events' THEN '[["detail_json","ingestion_event"]]' WHEN 'music_performances' THEN '[["broadcast_metadata","broadcast"]]' WHEN 'notices' THEN '[["links","notice_links"],["image_urls","strings"],["related_member_uids","member_uids"],["historical_related_people","historical_people"]]' WHEN 'pending_schedules' THEN '[["ranked_schedule_ids","schedule_ids"],["source_vod_ids","strings"]]' WHEN 'schedule_candidate_rejections' THEN '[["ranked_schedule_ids","schedule_ids"],["source_vod_ids","strings"]]' WHEN 'x_api_cache' THEN '[["value","x_cache"]]' WHEN 'x_posts' THEN '[["value","x_post"]]' WHEN 'youtube_api_cache' THEN '[["value","youtube_cache"]]' ELSE '[]' END) field;
