CREATE VIEW content_transition_invalid_json AS WITH RECURSIVE roots AS MATERIALIZED(SELECT * FROM content_transition_json_roots),nodes(transition_id,row_table,row_key,commit_seq,column_name,shape_json,value_json,valid_json) AS (
      SELECT transition_id,row_table,row_key,commit_seq,column_name,shape_json,value_json,valid_json FROM roots
      UNION ALL SELECT n.transition_id,n.row_table,n.row_key,n.commit_seq,n.column_name,CASE WHEN json_type(n.shape_json,'$.array') IS NOT NULL THEN json_quote(json_extract(n.shape_json,'$.array')) WHEN json_extract(n.shape_json,'$')='subject' THEN iif(EXISTS(SELECT 1 FROM json_each(json_extract('{"member":["kind","memberUid"],"entity":["kind","entityId"],"new_external":["kind","clientKey","displayName","entityKind"]}','$.'||json_extract(n.value_json,'$.kind'))) allowed WHERE allowed.value=child.key),'"scalar"','null') ELSE json_quote(json_extract(n.shape_json,'$.fields.'||child.key)) END,CASE child.type WHEN 'text' THEN json_quote(child.value) WHEN 'true' THEN 'true' WHEN 'false' THEN 'false' ELSE coalesce(CAST(child.value AS TEXT),'null') END,1 FROM nodes n CROSS JOIN json_each(CASE WHEN json_extract(n.shape_json,'$')<>'drop' AND json_type(n.value_json) IN ('array','object') THEN n.value_json ELSE '[]' END) child
    ) SELECT DISTINCT n.transition_id,n.row_table,n.row_key,n.commit_seq,n.column_name,'unknown JSON shape/member reference' reason FROM nodes n WHERE NOT coalesce((CASE WHEN n.valid_json=0 OR json_type(n.shape_json)='null' THEN 0 WHEN json_extract(n.shape_json,'$')='drop' OR json_type(n.value_json)='null' THEN 1 WHEN json_extract(n.shape_json,'$')='scalar' THEN json_type(n.value_json) IN ('text','integer','real','true','false') WHEN json_extract(n.shape_json,'$')='subject' THEN json_type(n.value_json)='object' AND json_extract('{"member":["kind","memberUid"],"entity":["kind","entityId"],"new_external":["kind","clientKey","displayName","entityKind"]}','$.'||json_extract(n.value_json,'$.kind')) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM json_each(json_extract('{"member":["kind","memberUid"],"entity":["kind","entityId"],"new_external":["kind","clientKey","displayName","entityKind"]}','$.'||json_extract(n.value_json,'$.kind'))) required WHERE json_type(n.value_json,'$.'||required.value) IS NULL) AND (json_extract(n.value_json,'$.kind')<>'member' OR (json_type(n.value_json,'$.memberUid')='integer' AND (n.commit_seq=0 AND EXISTS(SELECT 1 FROM members m WHERE m.uid=json_extract(n.value_json,'$.memberUid')) OR n.commit_seq>0 AND (SELECT j.after_json IS NOT NULL FROM content_transition_journal j WHERE j.transition_id=n.transition_id AND j.row_table='members' AND j.row_key=json_array(json_extract(n.value_json,'$.memberUid')) AND j.commit_seq<=n.commit_seq ORDER BY j.commit_seq DESC,j.seq DESC LIMIT 1)))) AND (json_extract(n.value_json,'$.kind')<>'entity' OR (json_type(n.value_json,'$.entityId')='text' AND length(json_extract(n.value_json,'$.entityId'))>0)) WHEN json_type(n.shape_json,'$.array') IS NOT NULL THEN json_type(n.value_json)='array' WHEN json_type(n.shape_json,'$.fields')='object' THEN json_type(n.value_json)='object' ELSE 0 END),0) UNION SELECT r.transition_id,r.row_table,r.row_key,r.commit_seq,r.column_name,'missing committed content reference' FROM roots r WHERE (r.row_table='music_ingestion_candidates' AND r.column_name='review_input_json' AND EXISTS(SELECT 1 FROM (SELECT json_extract(r.value_json,'$.song.songId') value,json_type(r.value_json,'$.song.songId') type) ref WHERE ref.type<>'null' AND (ref.type<>'text' OR NOT (r.commit_seq=0 AND EXISTS(SELECT 1 FROM "music_songs" target WHERE target.id=ref.value) OR r.commit_seq>0 AND coalesce((SELECT j.after_json IS NOT NULL FROM content_transition_journal j WHERE j.transition_id=r.transition_id AND j.row_table='music_songs' AND j.row_key=json_array(ref.value) AND j.commit_seq<=r.commit_seq ORDER BY j.commit_seq DESC,j.seq DESC LIMIT 1),0))))) OR (r.row_table='music_ingestion_candidates' AND r.column_name='review_input_json' AND EXISTS(SELECT 1 FROM (SELECT json_extract(ref0.value,'$.subject.entityId') value,json_type(ref0.value,'$.subject.entityId') type FROM json_each(r.value_json,'$.song.originalArtists') ref0) ref WHERE ref.type<>'null' AND (ref.type<>'text' OR NOT (r.commit_seq=0 AND EXISTS(SELECT 1 FROM "music_entities" target WHERE target.id=ref.value) OR r.commit_seq>0 AND coalesce((SELECT j.after_json IS NOT NULL FROM content_transition_journal j WHERE j.transition_id=r.transition_id AND j.row_table='music_entities' AND j.row_key=json_array(ref.value) AND j.commit_seq<=r.commit_seq ORDER BY j.commit_seq DESC,j.seq DESC LIMIT 1),0))))) OR (r.row_table='music_ingestion_candidates' AND r.column_name='review_input_json' AND EXISTS(SELECT 1 FROM (SELECT json_extract(ref0.value,'$.subject.entityId') value,json_type(ref0.value,'$.subject.entityId') type FROM json_each(r.value_json,'$.participants') ref0) ref WHERE ref.type<>'null' AND (ref.type<>'text' OR NOT (r.commit_seq=0 AND EXISTS(SELECT 1 FROM "music_entities" target WHERE target.id=ref.value) OR r.commit_seq>0 AND coalesce((SELECT j.after_json IS NOT NULL FROM content_transition_journal j WHERE j.transition_id=r.transition_id AND j.row_table='music_entities' AND j.row_key=json_array(ref.value) AND j.commit_seq<=r.commit_seq ORDER BY j.commit_seq DESC,j.seq DESC LIMIT 1),0)))));
