CREATE VIEW content_transition_identity_missing AS SELECT m.transition_id,m.commit_seq,m.row_key FROM content_transition_journal m JOIN content_transitions t ON t.id=m.transition_id WHERE m.row_table='members' AND m.after_json IS NOT NULL AND NOT (EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') approved WHERE json_extract(approved.value,'$.uid')=json_extract(m.after_json,'$.uid'))) AND NOT EXISTS(SELECT 1 FROM content_transition_identity_proofs p WHERE p.transition_id=m.transition_id AND p.member_uid=json_extract(m.after_json,'$.uid') AND p.source_name=json_extract(m.after_json,'$.name') AND p.protocol=t.protocol AND p.generation=t.generation AND p.manifest_digest=t.manifest_digest AND p.manifest_revision=t.manifest_revision);
