CREATE VIEW content_transition_projected_identities AS SELECT e.transition_id,e.commit_seq,e.row_key,coalesce((SELECT p.target_entity_id FROM content_transition_identity_proofs p WHERE p.transition_id=e.transition_id AND p.member_uid=coalesce(json_extract(e.image_json,'$.member_uid'),(SELECT json_extract(j.after_json,'$.member_uid') FROM content_transition_journal j WHERE j.transition_id=e.transition_id AND j.row_table='music_entities' AND j.row_key=e.row_key AND j.commit_seq<=e.commit_seq AND json_extract(j.after_json,'$.member_uid') IS NOT NULL ORDER BY j.seq DESC LIMIT 1)) LIMIT 1),json_extract(e.image_json,'$.id')) id,json_extract(e.image_json,'$.entity_kind') kind,json_extract(e.image_json,'$.normalized_name') normalized,json_extract(e.image_json,'$.slug') slug FROM content_transition_identity_images e JOIN content_transitions t ON t.id=e.transition_id WHERE e.row_table='music_entities' AND (json_extract(e.image_json,'$.member_uid') IS NULL OR NOT (EXISTS(SELECT 1 FROM json_each(t.plan_json,'$.members') approved WHERE json_extract(approved.value,'$.uid')=json_extract(e.image_json,'$.member_uid'))))
    UNION ALL SELECT m.transition_id,m.commit_seq,m.row_key,p.target_entity_id,'person',p.normalized_name,p.target_entity_id FROM content_transition_identity_images m JOIN content_transition_identity_proofs p ON p.transition_id=m.transition_id AND p.member_uid=json_extract(m.image_json,'$.uid') AND p.source_name=json_extract(m.image_json,'$.name') WHERE m.row_table='members' AND NOT EXISTS(SELECT 1 FROM content_transition_identity_images e WHERE e.transition_id=m.transition_id AND e.commit_seq=m.commit_seq AND e.row_table='music_entities' AND json_extract(e.image_json,'$.member_uid')=json_extract(m.image_json,'$.uid'));
