CREATE TRIGGER content_identity_proof_insert BEFORE INSERT ON content_transition_identity_proofs BEGIN SELECT RAISE(ABORT,'content_identity_internal_proof_required') WHERE NOT EXISTS(SELECT 1 FROM content_transition_permits p JOIN content_transitions t ON t.id=p.transition_id WHERE p.transition_id=NEW.transition_id AND p.mode='identity' AND t.local_site=t.source_site AND t.fence_json IS NULL); SELECT RAISE(ABORT,'content_identity_binding_immutable') WHERE EXISTS(SELECT 1 FROM content_transition_identity_proofs p WHERE p.transition_id=NEW.transition_id AND p.member_uid=NEW.member_uid AND (p.first_commit<>NEW.first_commit OR p.target_entity_id<>NEW.target_entity_id)); END;
